PREFIX : <http://valuenet/ontop/>
SELECT DISTINCT ?museumName WHERE {
  {
    SELECT (MIN(?staffCount) AS ?minStaffCount) WHERE {
      ?museum a <http://valuenet/ontop/museum> .
      ?museum <http://valuenet/ontop/open_year> ?openYear .
      ?museum <http://valuenet/ontop/num_of_staff> ?staffCount .
      FILTER(?openYear > 2010)
    }
  }
  ?museum a <http://valuenet/ontop/museum> .
  ?museum <http://valuenet/ontop/num_of_staff> ?staffCount .
  ?museum <http://valuenet/ontop/name> ?museumName .
  FILTER(?staffCount > ?minStaffCount)
}

PREFIX : <http://valuenet/ontop/>
SELECT ?visitor_id ?name ?age
WHERE {
  ?visit <http://valuenet/ontop/ref-visitor> ?visitor .
  ?visitor <http://valuenet/ontop/id> ?visitor_id .
  ?visitor <http://valuenet/ontop/name> ?name .
  ?visitor <http://valuenet/ontop/age> ?age .

  {
    SELECT ?visitor (COUNT(?visit) AS ?visit_count)
    WHERE {
      ?visit <http://valuenet/ontop/ref-visitor> ?visitor .
    }
    GROUP BY ?visitor
    HAVING (COUNT(?visit) > 1)
  }
}

